package com.studentswap.backend;
import com.studentswap.backend.entity.*;
import com.studentswap.backend.repository.*;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.math.BigDecimal;
@RestController @RequestMapping("/api") @CrossOrigin(origins={"http://localhost:5175","http://localhost:5173","http://127.0.0.1:5175","http://127.0.0.1:5173"})
public class StudentSwapController {
 private final CategoryRepository cats; private final ListingRepository listings; private final ContactRequestRepository contacts;
 private final AppUserRepository users; private final ListingOwnerRepository owners; private final BuyerMessageRepository messages;
 private final UserSessionRepository sessions; private final SessionService tokens; private final PasswordEncoder encoder;
 public StudentSwapController(CategoryRepository a,ListingRepository b,ContactRequestRepository c,AppUserRepository d,ListingOwnerRepository e,BuyerMessageRepository f,UserSessionRepository g,SessionService h,PasswordEncoder i){cats=a;listings=b;contacts=c;users=d;owners=e;messages=f;sessions=g;tokens=h;encoder=i;}
 private boolean admin(Authentication a){return a!=null&&a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));}
 private Long uid(Authentication a){if(a==null||admin(a))return null;try{return Long.parseLong(a.getName());}catch(Exception ex){return null;}}
 private ResponseEntity<?> error(HttpStatus s,String msg){return ResponseEntity.status(s).body(Map.of("error",msg));}
 private Map<String,Object> profile(AppUser u){return Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role","STUDENT");}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status","OK");}
 @GetMapping("/categories") public List<Category> categories(){return cats.findAll();}
 @GetMapping("/listings") public List<Map<String,Object>> available(){return listings.findByListingStatus("AVAILABLE").stream().map(this::listingView).toList();}
 private Map<String,Object> listingView(Listing l){Map<String,Object> m=new LinkedHashMap<>();m.put("listingId",l.getListingId());m.put("title",l.getTitle());m.put("description",l.getDescription());m.put("price",l.getPrice());m.put("conditionStatus",l.getConditionStatus());m.put("listingStatus",l.getListingStatus());m.put("categoryId",l.getCategoryId());m.put("imageUrl",l.getImageUrl());m.put("sellerId",l.getSellerId());Long id=owners.findById(l.getListingId()).map(ListingOwner::getUserId).orElse(null);m.put("ownerId",id);m.put("sellerName",id==null?"Campus seller":users.findById(id).map(AppUser::getName).orElse("Campus seller"));return m;}
 @PostMapping("/auth/register") public ResponseEntity<?> register(@RequestBody Map<String,String> data){String name=data.getOrDefault("name","").trim(),email=data.getOrDefault("email","").trim().toLowerCase(Locale.ROOT),password=data.getOrDefault("password","");if(name.length()<2||name.length()>100||!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")||email.length()>190||password.length()<8||password.length()>100)return error(HttpStatus.BAD_REQUEST,"Use a name, valid email and password of 8–100 characters.");if(users.findByEmail(email).isPresent())return error(HttpStatus.CONFLICT,"This email already has an account.");AppUser u=new AppUser();u.setName(name);u.setEmail(email);u.setPasswordHash(encoder.encode(password));users.save(u);return ResponseEntity.status(201).body(Map.of("token",tokens.issue(u.getId()),"user",profile(u)));}
 @PostMapping("/auth/login") public ResponseEntity<?> login(@RequestBody Map<String,String> data){String email=data.getOrDefault("email","").trim().toLowerCase(Locale.ROOT);Optional<AppUser> u=users.findByEmail(email);if(u.isEmpty()||!encoder.matches(data.getOrDefault("password",""),u.get().getPasswordHash()))return error(HttpStatus.UNAUTHORIZED,"Incorrect email or password.");return ResponseEntity.ok(Map.of("token",tokens.issue(u.get().getId()),"user",profile(u.get())));}
 @GetMapping("/auth/me") public ResponseEntity<?> me(Authentication a){Long id=uid(a);return id==null?error(HttpStatus.FORBIDDEN,"Student account required."):users.findById(id).<ResponseEntity<?>>map(u->ResponseEntity.ok(profile(u))).orElseGet(()->error(HttpStatus.UNAUTHORIZED,"Session expired."));}
 @PostMapping("/auth/logout") public Map<String,String> logout(@RequestHeader(value="Authorization",required=false)String auth){if(auth!=null&&auth.startsWith("Bearer "))tokens.revoke(auth.substring(7));return Map.of("message","Logged out");}
 @DeleteMapping("/auth/me") @Transactional public ResponseEntity<?> deleteAccount(Authentication a){Long id=uid(a);if(id==null)return error(HttpStatus.FORBIDDEN,"Student account required.");for(ListingOwner o:owners.findByUserId(id)){messages.findByListingId(o.getListingId()).forEach(messages::delete);owners.delete(o);listings.deleteById(o.getListingId());}for(BuyerMessage m:messages.findByBuyerIdOrderByCreatedAtDesc(id))messages.delete(m);sessions.findByUserId(id).forEach(sessions::delete);users.deleteById(id);return ResponseEntity.ok(Map.of("message","Account deleted"));}
 private String validate(Listing l){if(l.getTitle()==null||l.getTitle().isBlank()||l.getTitle().length()>150)return "Title must be 1–150 characters.";if(l.getPrice()==null||l.getPrice().compareTo(BigDecimal.ZERO)<0)return "Price must be zero or higher.";if(!Set.of("LIKE_NEW","GOOD","FAIR").contains(l.getConditionStatus()))return "Choose a valid condition.";if(l.getCategoryId()==null||!cats.existsById(l.getCategoryId()))return "Choose a valid category.";if(l.getImageUrl()!=null&&l.getImageUrl().length()>500)return "Image URL is too long.";return null;}
 @PostMapping("/listings") @Transactional public ResponseEntity<?> create(@RequestBody Listing input,Authentication a){Long id=uid(a);if(id==null)return error(HttpStatus.FORBIDDEN,"Log in as a student to sell.");String invalid=validate(input);if(invalid!=null)return error(HttpStatus.BAD_REQUEST,invalid);input.setListingId(null);input.setListingStatus("AVAILABLE");input.setSellerId(1L);Listing saved=listings.save(input);owners.save(new ListingOwner(saved.getListingId(),id));return ResponseEntity.status(201).body(listingView(saved));}
 private boolean canManage(Long listingId,Authentication a){return admin(a)||Objects.equals(owners.findById(listingId).map(ListingOwner::getUserId).orElse(null),uid(a))&&uid(a)!=null;}
 @PutMapping("/listings/{id}") public ResponseEntity<?> edit(@PathVariable Long id,@RequestBody Listing input,Authentication a){Optional<Listing> o=listings.findById(id);if(o.isEmpty())return error(HttpStatus.NOT_FOUND,"Listing not found.");if(!canManage(id,a))return error(HttpStatus.FORBIDDEN,"You can edit only your own listings.");String invalid=validate(input);if(invalid!=null)return error(HttpStatus.BAD_REQUEST,invalid);Listing l=o.get();l.setTitle(input.getTitle().trim());l.setDescription(input.getDescription());l.setPrice(input.getPrice());l.setConditionStatus(input.getConditionStatus());l.setCategoryId(input.getCategoryId());if(input.getImageUrl()!=null)l.setImageUrl(input.getImageUrl());return ResponseEntity.ok(listingView(listings.save(l)));}
 @DeleteMapping("/listings/{id}") @Transactional public ResponseEntity<?> delete(@PathVariable Long id,Authentication a){if(!listings.existsById(id))return error(HttpStatus.NOT_FOUND,"Listing not found.");if(!canManage(id,a))return error(HttpStatus.FORBIDDEN,"You can delete only your own listings.");messages.findByListingId(id).forEach(messages::delete);owners.deleteById(id);listings.deleteById(id);return ResponseEntity.ok(Map.of("message","Listing deleted"));}
 @PostMapping("/messages") public ResponseEntity<?> sendMessage(@RequestBody Map<String,Object> data,Authentication a){Long buyer=uid(a);if(buyer==null)return error(HttpStatus.FORBIDDEN,"Log in to contact a seller.");Long listingId;try{listingId=Long.valueOf(String.valueOf(data.get("listingId")));}catch(Exception ex){return error(HttpStatus.BAD_REQUEST,"Invalid listing ID.");}String msg=String.valueOf(data.getOrDefault("message","")).trim();if(msg.isBlank()||msg.length()>1000)return error(HttpStatus.BAD_REQUEST,"Message must be 1–1000 characters.");Optional<Listing> listing=listings.findById(listingId);if(listing.isEmpty()||!"AVAILABLE".equals(listing.get().getListingStatus()))return error(HttpStatus.NOT_FOUND,"Listing unavailable.");Long seller=owners.findById(listingId).map(ListingOwner::getUserId).orElse(null);if(seller==null)return error(HttpStatus.BAD_REQUEST,"This legacy listing has no registered seller yet.");if(seller.equals(buyer))return error(HttpStatus.BAD_REQUEST,"You cannot message yourself.");BuyerMessage m=new BuyerMessage();m.setListingId(listingId);m.setBuyerId(buyer);m.setSellerId(seller);m.setMessage(msg);messages.save(m);return ResponseEntity.status(201).body(Map.of("message","Message sent to seller."));}
 @GetMapping("/messages") public ResponseEntity<?> inbox(Authentication a){Long id=uid(a);if(id==null)return error(HttpStatus.FORBIDDEN,"Student account required.");return ResponseEntity.ok(messages.findBySellerIdOrderByCreatedAtDesc(id).stream().map(m->{Map<String,Object> x=new LinkedHashMap<>();x.put("id",m.getId());x.put("listingId",m.getListingId());x.put("listingTitle",listings.findById(m.getListingId()).map(Listing::getTitle).orElse("Listing"));x.put("buyerName",users.findById(m.getBuyerId()).map(AppUser::getName).orElse("Student"));x.put("buyerEmail",users.findById(m.getBuyerId()).map(AppUser::getEmail).orElse(""));x.put("message",m.getMessage());x.put("createdAt",m.getCreatedAt());return x;}).toList());}
 @PostMapping("/contact") public ResponseEntity<?> contact(@RequestBody ContactRequest req){if(req.getRequesterName()==null||req.getRequesterName().isBlank()||req.getRequesterEmail()==null||!req.getRequesterEmail().matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")||req.getMessage()==null||req.getMessage().isBlank()||req.getMessage().length()>1000)return error(HttpStatus.BAD_REQUEST,"Valid name, email and message are required.");req.setRequestId(null);req.setStatus("PENDING");req.setCreatedAt(null);return ResponseEntity.status(201).body(contacts.save(req));}
 @GetMapping("/admin/contact-requests") public List<ContactRequest> adminContacts(){return contacts.findByStatusOrderByCreatedAtDesc("PENDING");}

  @DeleteMapping("/admin/contact-requests/{id}")
  public ResponseEntity<?> deleteContactRequest(@PathVariable Long id) {
    if (!contacts.existsById(id)) {
      return error(HttpStatus.NOT_FOUND, "Contact request not found.");
    }
    contacts.deleteById(id);
    return ResponseEntity.noContent().build();
  }
}
